    @patch("subprocess.run")
    def test_run_command_timeout(self, mock_run, runtime):
        """Verify behavior when the subprocess times out."""
        mock_run.side_effect = subprocess.TimeoutExpired(cmd=["podman"], timeout=300)

        with pytest.raises(ContainerExecutionError) as excinfo:
            runtime.run_command("alpine", ["sleep", "1000"], timeout=1)
            
